      SUBROUTINE DECPAR(NDICT,DICT,NCPAR,NPPAR,NPF)C---- DECODE PARAMETER LISTC-----------------------------------------------------------------------      CHARACTER*15    DICT(NDICT)      INTEGER         NPPAR(NCPAR)C-----------------------------------------------------------------------C---- LOGICAL UNITS, POINTERS AND COUNTERS FOR I/OC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1E.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2C.CIN'      INCLUDE 'DATUM.CIN'      INCLUDE 'ELM14A.CIN'      INCLUDE 'ICODE.CIN'      INCLUDE 'ILAST.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'INSERT.CIN'      INCLUDE 'IODATA.CIN'      INCLUDE 'IOFLAG.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'KNAME.CIN'      INCLUDE 'LBDAT.CIN'      INCLUDE 'LNAME.CIN'      INCLUDE 'NDICT.CIN'      INCLUDE 'NUMREP.CIN'      INCLUDE 'OUTFIL.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARLOC.CIN'      INCLUDE 'PARVAL.CIN'      INCLUDE 'RDBUFF.CIN'      INCLUDE 'RDCARD.CIN'      INCLUDE 'RDCHAR.CIN'      INCLUDE 'RDPRNT.CIN'      INCLUDE 'RDWRDS.CIN'      INCLUDE 'VARY.CIN'C-----------------------------------------------------------------------      CHARACTER*1     COLON, CLETS(15), CLTMP(15)      CHARACTER*13    NUMC      CHARACTER*15    CWORD, CWTMP, DAUGHTER1, DAUGHTER2, KPARA, LOCATE,      1                NAME, PARENT, PLACE      LOGICAL         FLAG      EQUIVALENCE     (CWORD,CLETS(1)), (CWTMP,CLTMP(1))      EQUIVALENCE     (LAKE,FAKE)C-----------------------------------------------------------------------      DATA COLON /':'/, LOCATE /'LOCATION'/, PLACE /'PLACE   '/      DATA PARENT /'PARENT'/, DAUGHTER1 /'DAUGHTER1'/,      1     DAUGHTER2 /'DAUGHTER2'/      DATA NAME /'NAME'/      DATA NUMC /'0123456789.+-'/C      ERROR = .FALSE.      MADNO = .FALSE.      NDSAV = NDICT      NCPARA = NCPAR      NCDO = MIN(NCPAR,15)      DO 10 J = 1, NCDO   10 NPORDR(J) = NPPAR(J)      NWRDS = 0      INAMS = 1      IPARM = 0CC---- ANOTHER PARAMETER?C  100 CALL RDNEXT      IF (ENDFIL) GO TO 600      IF (ITEM .NE. QUOTE .AND. ITEM .NE. APOST     1    .AND. NWRDS .GE. NPF) THEN        CALL RDBACK        GO TO 500      ENDIF      IF (ITEM .EQ. SEMI .OR. ITEM .EQ. DOLLAR .OR. ITEM .EQ. ASTER)     1    GO TO 500      IF (ITEM .EQ. COMMA) THEN        CALL RDNEXT        IF (ENDFIL) GO TO 600      ENDIFCC---- PARAMETER KEYWORDC      IF (INDEX(ALPHA,ITEM) .NE. 0) THEN        CALL RDWORD(KNAME,LNAME)        IF (LNAME .EQ. 0) THEN          CALL RDFAIL          WRITE (NOUT,910)          GO TO 200        ENDIFCC---- COLON?C        CALL RDNEXT        IF (ENDFIL) GO TO 600        IF (ITEM .EQ. COLON) THEN          CALL RDFAIL          ERROR = .TRUE.          CALL RDFIND (';')          IF (ENDFIL) GO TO 600          GO TO 500        ENDIFCC---- EQUALS SIGN?C        LLC = MAX0(LNAME,2)        CALL RDLOOK(KNAME,LNAME,DICT,1,NDICT,IPARM)        IF (KNAME(1:4) .EQ. 'TYPE') GO TO 170        IF (KNAME .EQ. LOCATE(1:LLC) .OR. KNAME .EQ. PLACE(1:LLC))     1      GO TO 150        IF (KNAME .EQ. 'FLAG') GO TO 160        IF (NTYPE .EQ. 16 .AND. (KNAME .EQ. PARENT(1:LLC)      1      .OR. KNAME .EQ. DAUGHTER1(1:LLC)      2      .OR. KNAME .EQ. DAUGHTER2(1:LLC))) GO TO 175         IF (IPARM .NE. 0) GO TO 120        IF (NTYPE .EQ. 0 .OR. NTYPE .EQ. 13) THEN          OUTFIL = KNAME          LOUTF = LNAME          CALL RDBACK          GO TO 180        ENDIFC        IF (NTYPE .EQ. 8) THEN           CALL DECMIS(NELMN)          IF (NELMN .EQ. 0) GO TO 500          GO TO 180        ENDIFC        IF (NTYPE .EQ. 10) THEN          CALL DECFIT(INAME,INAMS)          IF (INAME .NE. 0) GO TO 120        ENDIFC        IF (NTYPE .EQ. 12) THEN          CALL FNCORR(KNAME,LNAME,INAME)          IF (INAME .NE. 0) GO TO 120        ENDIFC        IF (NTYPE .EQ. 14) THEN          CALL DECARB(INAME)          IF (INAME .NE. 0) GO TO 120        ENDIFC        IF (NTYPE .EQ. 15) THEN          IF (LBDAT .EQ. BLANK) THEN            LBDAT = KNAME            GO TO 120          ENDIF        ENDIFC        IF (NTYPE .EQ. 38) THEN          CALL DECPLOT(FLAG,INAMS)          IF (ENDFIL) GO TO 600          IF (FLAG) GO TO 500          GO TO 120        ENDIFC        CALL RDFAIL        GO TO 200C  120   MADNO = .TRUE.        NWRDS = NWRDS + 1        IF (ITEM .EQ. EQUAL) THEN          IPTYP(IPARM) = 1          CALL DECEXP          IF (ENDFIL) GO TO 600          FLAG = ERROR          IOPERS(IPARM) = IOPER          IF (IPDAT(IPARM) .NE. 100 .AND. IOPER .EQ. 0     1        .AND. (INDS .EQ. 0 .OR. INSERT)) THEN            NEL = NEL - 1            I = ILAST            IF (IPTYP(IPARM) .EQ. 1) THEN              IF (NTYPE .LT. 50 .OR. (NTYPE .GE. 50 .AND. IPARM .NE. 5))      1          PDATA(IPARM) = DATA(I+1)              ELSE                PDATA(IPARM) = DATA(I+3)              ENDIF          ENDIF          IF (IOPER .EQ. 1) THEN            NWORD = NPVAR + 2            NDESC = 1            LAKE = 30            DATUM(1) = FAKE            VARY(2) = 99            IADR = ISTOR(NEL) + 4            LAKE = I + 1            DATA(IADR) = FAKE            TIE(IADR) = 100            LAKE = I + 1            PDATA(IPARM) = FAKE            IPTYP(IPARM) = 1            IPDAT(IPARM) = 100            CALL ELSTOR          ENDIF          IF (FLAG) GO TO 200        ELSE          CALL RDBACK          IF (NTYPE .EQ. 15 .AND. IPARM .EQ. 0) GO TO 180          IF (NTYPE .NE. 38) IPTYP(IPARM) = -2        ENDIF        GO TO 180CC---- LOCATION SPECIFICATION FOR MARKERC  150   LDATA = BLANK        IF (ITEM .EQ. EQUAL) THEN          CALL RDNEXT          IF (ENDFIL) GO TO 600          CALL RDWORD(LDATA,LOCN)          IF (LOCN .EQ. 0) THEN            CALL RDFAIL            WRITE (NOUT,910)            GO TO 200          ENDIF        ENDIF        GO TO 180CC---- FLAG SPECIFICATION FOR HISTOGRAMC  160   LRDFLG = BLANK        IF (ITEM .EQ. EQUAL) THEN          CALL RDNEXT          IF (ENDFIL) GO TO 600          CALL RDWORD(LRDFLG,LFLN)          IF (LFLN .EQ. 0) THEN            CALL RDFAIL            WRITE (NOUT,910)            GO TO 200          ENDIF        ENDIF        GO TO 180CC---- TYPE SPECIFICATION?C  170   IF (ITEM .EQ. EQUAL) THEN          NWRDS = NWRDS + 1          IPTYP(IPARM) = 1          CALL RDNEXT          IF (ENDFIL) GO TO 600          CALL RDTYPE(KTYPE,LTYPE)        ENDIF        GO TO 180CC---- PARTICLE NAME AND CHARGEC  175   IF (ITEM .EQ. EQUAL) THEN          IPTYP(IPARM) = 1          CALL RDNEXT          IF (INDEX(ALPHA,ITEM) .NE. 0) THEN            CALL RDWORD(KNAME,LNAME)            LBDAT = KNAME          ENDIF        ELSE          IPTYP(IPARM) = -2          CALL RDBACK        ENDIF CC---- SEPARATOR?C  180   CALL RDNEXT        IF (ENDFIL) GO TO 600        IF (ITEM .EQ. COMMA) GO TO 100        IF (ITEM .EQ. SEMI .OR. ITEM .EQ. DOLLAR .OR. ITEM .EQ. ASTER)     1      GO TO 500        IF (ITEM .EQ. QUOTE .OR. ITEM .EQ. APOST) THEN          CALL RDBACK          GO TO 100        ENDIFCC---- ERROR RECOVERYC  200   CALL RDFIND(',;')        IF (ENDFIL) GO TO 600        ERROR = .TRUE.        GO TO 100CC---- NUMERICAL VALUEC      ELSE IF (INDEX(NUMC,ITEM) .NE. 0) THEN        IF (.NOT. MADNO) THEN          CALL RDNUMB(VALUE,IVALUE,FLAG)          IF (ENDFIL) GO TO 600          IF (NWRDS .GT. NCPAR) THEN            ERROR = .TRUE.          ELSE            NWRDS = NWRDS + 1            IF (NWRDS .LE. 15) IPARM = NPPAR(NWRDS)            IF (NWRDS .GT. 15) IPARM = NWRDS            IF (NTYPE .EQ. 16 .AND. INT(PDATA(1)) .EQ. 14) THEN              LAKE = IVALUE              PDATA(IPARM) = FAKE              CALL SEEDIT            ELSE              PDATA(IPARM) = VALUE            ENDIF            IPTYP(IPARM) = 1          ENDIF          GO TO 100        ELSE          CALL RDFIND(',;')          IF (ENDFIL) GO TO 600          ERROR = .TRUE.          GO TO 100        ENDIFCC---- LABELC      ELSE IF (ITEM .EQ. QUOTE .OR. ITEM .EQ. APOST) THEN        CALL RDSTRG (CWORD, 15, L)        IF (L .GT. 15) WRITE (NOUT, 9350)        IF (LABLE .NE. BLANK) WRITE (NOUT, 9360) LABLE        LL = 0        CWTMP = BLANK        DO 410 LLL = 1, L        IF (CLETS(LLL) .NE. BLANK) THEN          LL = LL + 1          CLTMP(LL) = CLETS(LLL)        ENDIF  410   CONTINUE        L = LL        CWORD = CWTMP        LBDAT = CWORD        LABLE = CWORD        GO TO 100CC---- NOTHING RECOGNIZABLEC      ELSE        CALL RDWARN      ENDIF  500 NWORD = NWRDS + 1  600 CONTINUE      RETURNC-----------------------------------------------------------------------  910 FORMAT(' *** ERROR *** PARAMETER KEYWORD EXPECTED'/' ') 9350 FORMAT ('0NEXT LABEL TRUNCATED TO 15 CHARS.') 9360 FORMAT (8H0LABEL ",A4,33H" ON NEXT ELEMENT WAS OVERWRITTEN) 9370 FORMAT ('0NUMBERS MAY NOT FOLLOW KEYWORD PARAMETERS')C-----------------------------------------------------------------------      END